# Original SkillsLayer.j2 retained verbatim as a Python string.
ORIGINAL_TEMPLATE = "{% if loaded_skills %}\n<SKILLS>\n<purpose>\nSkills are private workflow capabilities available through the sandbox.\nThey are NOT callable tool names — each one is engaged by reading its\ninstructions and following them. The only tool that starts a skill is\n`bash`.\n</purpose>\n\n<available_skills>\n{% for skill in loaded_skills %}\n- `{{ skill.name }}` — {{ skill.description }}\n{% endfor %}\n</available_skills>\n\n<workflow>\nWhen a user's request matches one of the skills above:\n1. Run `bash` with the command `read_skill <skill-name>` to load the\n   skill's instructions, passing the capability name above as\n   `<skill-name>`.\n2. Follow the workflow described in those instructions, using `bash` and\n   any other tools as the skill directs.\n3. Reply with only the final result and any user-facing artifact names.\n</workflow>\n\n<rules>\n- `bash` is the ONLY way to engage a skill. Never treat a skill name as a\n  callable tool, and never write a `bash` command as plain text instead of\n  actually invoking the tool.\n- Don't invent skill contents. If you haven't loaded a skill via\n  `read_skill`, you don't know what it does — load it first.\n- Never expose implementation details to the user: no skill paths,\n  environment variables, filenames, script paths, workspace mount names,\n  or the shell commands you ran. Describe only the user-facing result.\n</rules>\n</SKILLS>\n{% endif %}"
